  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * 1. Summary: Validates whether a booking request satisfies all business rules regarding trip existence, seat availability, temporal constraints, and customer schedule conflicts.
   * 2. Algorithm:
   *    1. If trip, customer, or bookingDate is null, return false.
   *    2. If trip.numberOfSeats < this.numberOfSeats, return false.
   *    3. Calculate time difference between bookingDate and (trip.departureDate + trip.departureTime). If difference <= 2 hours, return false.
   *    4. For each existing booking in customer.bookings:
   *       a. If existingBooking.trip.departureDate == this.trip.departureDate AND existingBooking.overlapsWith(this.trip) is true, return false.
   *    5. Return true.
   * 3. Related Features: trip, customer, bookingDate, numberOfSeats, customer.bookings, trip.numberOfSeats, trip.departureDate, trip.departureTime
   * 4. Related Classes: Trip, Customer
   * 5. Input: None (method operates on instance attributes: trip, customer, bookingDate, numberOfSeats).
   * 6. Output: boolean (true if booking is eligible, false otherwise).
   * 7. Pre-condition: The Booking instance and its referenced trip and customer objects are initialized and non-null.
   * 8. Post-condition: No state modification. Returns eligibility status. Actual seat reduction is deferred to updateTripSeats() upon successful booking confirmation.
   * <!-- end-model-doc -->
   * @model kind="operation"
   *        annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean isBookingEligible()
  {
    if (getTrip() == null || getCustomer() == null || getBookingDate() == null)
    {
      return false;
    }
    
    if (getTrip().getNumberOfSeats() < getNumberOfSeats())
    {
      return false;
    }
    
    String depTimeStr = getTrip().getDepartureTime();
    int colonIdx = depTimeStr.indexOf(':');
    int hour = Integer.parseInt(depTimeStr.substring(0, colonIdx));
    int minute = (colonIdx != -1 && colonIdx + 1 < depTimeStr.length()) ? Integer.parseInt(depTimeStr.substring(colonIdx + 1)) : 0;
    long timeMillis = (hour * 60L + minute) * 60L * 1000L;
    long departureMillis = getTrip().getDepartureDate().getTime() + timeMillis;
    long bookingMillis = getBookingDate().getTime();
    long diff = Math.abs(departureMillis - bookingMillis);
    
    if (diff <= 2 * 60 * 60 * 1000)
    {
      return false;
    }
    
    for (Booking existingBooking : getCustomer().getBookings())
    {
      if (existingBooking.getTrip().getDepartureDate().equals(getTrip().getDepartureDate()) && 
          existingBooking.overlapsWith(getTrip()))
      {
        return false;
      }
    }
    
    return true;
  }

